const j = $input.first().json;
const action = String(j.action || '').toLowerCase().trim();
let rel = String(j.path || '').trim();
while (rel.length && rel.charAt(0) === '/') rel = rel.slice(1);
const client = String(j.clientName || '').trim();
const key = String(j.key || '').trim();
const envFile = String(j.envFile || '').toLowerCase().trim();
let val = j.value != null ? String(j.value) : '';
val = val.split(String.fromCharCode(10)).join(' ').split(String.fromCharCode(13)).join('').split('"').join('');
if (val.length > 2000) val = val.slice(0, 2000);
const contentStr = j.content != null ? String(j.content) : '';
let runId = String(j.runId || 'run');
let cleanRun = '';
for (let i = 0; i < runId.length; i++) { const c = runId.charAt(i); if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c === '_' || c === '-') cleanRun += c; }
if (!cleanRun) cleanRun = 'run';
let attempt = ''; const ar = String(j.attempt || '0'); for (let i = 0; i < ar.length; i++) { const c = ar.charAt(i); if (c >= '0' && c <= '9') attempt += c; } if (!attempt) attempt = '0';
const BASE = '/opt/ansible';
function out(o) { return [{ json: o }]; }
function block(reason) { return out({ allowed: false, action: action, mode: 'blocked', message: 'BLOCKED: ' + reason, preparedCommand: 'echo BLOCKED' }); }
function lowerDash(s) { if (!s.length) return false; for (let i = 0; i < s.length; i++) { const c = s.charAt(i); if (!((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c === '-')) return false; } return true; }
function safePath(s) { if (!s.length) return false; if (s.indexOf('..') !== -1) return false; for (let i = 0; i < s.length; i++) { const c = s.charAt(i); if (!((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c === '.' || c === '_' || c === '-' || c === '/')) return false; } return true; }
function b64(s) { return Buffer.from(s, 'utf8').toString('base64'); }
if (!lowerDash(client)) return block('invalid clientName');
const CD = 'clients/' + client + '/';
const BAK = BASE + '/backups/' + cleanRun;
function writeCmd(path, contentB64, bakName) {
  return 'mkdir -p ' + BAK + ' && cp -a ' + BASE + '/' + path + ' ' + BAK + '/' + bakName + ' 2>/dev/null; echo ' + contentB64 + ' | base64 -d > ' + BASE + '/' + path + ' && echo "=== DIFF ===" && diff -u ' + BAK + '/' + bakName + ' ' + BASE + '/' + path + ' 2>/dev/null | head -c 3000; echo; echo "WROTE_OK:' + path + '"';
}
function appendLineCmd(path, lineB64, removalKey, bakName) {
  return 'mkdir -p ' + BAK + ' && cp -a ' + BASE + '/' + path + ' ' + BAK + '/' + bakName + ' 2>/dev/null; grep -v "^' + removalKey + '" ' + BASE + '/' + path + ' > ' + BASE + '/' + path + '.tmp 2>/dev/null; echo ' + lineB64 + ' | base64 -d >> ' + BASE + '/' + path + '.tmp; mv ' + BASE + '/' + path + '.tmp ' + BASE + '/' + path + ' && echo "=== DIFF ===" && diff -u ' + BAK + '/' + bakName + ' ' + BASE + '/' + path + ' 2>/dev/null | head -c 3000; echo; echo SET_OK';
}
if (action === 'read') {
  if (!safePath(rel)) return block('bad path');
  const low = rel.toLowerCase();
  if (low.indexOf('ssh-keys/') !== -1 || low.indexOf('vault') !== -1 || low.slice(-4) === '.key' || low.slice(-4) === '.pem') return block('secret path');
  const clientOk = (rel === CD + 'vars.yml' || rel === CD + 'inventory.ini' || rel === CD + 'modsec-overrides.conf' || rel === CD + 'frontend.env' || rel === CD + 'backend.env');
  const mainOk = (rel.indexOf('roles/') === 0 || rel.indexOf('playbooks/') === 0 || rel === 'group_vars/all.yml');
  if (!clientOk && !mainOk) return block('read not permitted: ' + rel);
  return out({ allowed: true, action: 'read', mode: 'read', safePath: rel, preparedCommand: 'cat ' + BASE + '/' + rel + ' 2>&1 | head -c 12000' });
}
if (action === 'write_waf') {
  const path = CD + 'modsec-overrides.conf';
  return out({ allowed: true, action: 'write_waf', mode: 'write', safePath: path, preparedCommand: writeCmd(path, b64(contentStr), 'modsec-overrides.conf.attempt' + attempt + '.bak') });
}
if (action === 'set_var') {
  const allowed = ['app_name', 'app_domain', 'api_domain', 'app_path', 'git_repo', 'git_branch', 'react_repo', 'react_branch', 'react_build_cmd', 'react_output_dir', 'react_build_path', 'react_serve_path', 'deploy_react', 'split_domain', 'ssl_email', 'db_host', 'db_name', 'db_user', 'node_max_heap_mb'];
  if (allowed.indexOf(key) === -1) return block('key not editable: ' + key);
  const unquoted = (key === 'deploy_react' || key === 'split_domain' || key === 'node_max_heap_mb');
  const line = unquoted ? (key + ': ' + val) : (key + ': "' + val + '"');
  const path = CD + 'vars.yml';
  return out({ allowed: true, action: 'set_var', mode: 'write', safePath: path, key: key, preparedCommand: appendLineCmd(path, b64(line), key + ':', 'vars.yml.attempt' + attempt + '.bak') });
}
if (action === 'set_env') {
  if (envFile !== 'frontend' && envFile !== 'backend') return block('envFile must be frontend or backend');
  const K = key.toUpperCase();
  if (K.indexOf('PASSWORD') !== -1 || K.indexOf('SECRET') !== -1 || K.indexOf('TOKEN') !== -1 || K === 'APP_KEY' || K.indexOf('_KEY') !== -1) return block('env key protected: ' + key);
  let kOk = key.length > 0; for (let i = 0; i < key.length; i++) { const c = key.charAt(i); if (!((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c === '_')) kOk = false; }
  if (!kOk) return block('invalid env key');
  const line = key + '=' + val;
  const path = CD + (envFile === 'frontend' ? 'frontend.env' : 'backend.env');
  return out({ allowed: true, action: 'set_env', mode: 'write', safePath: path, key: key, preparedCommand: appendLineCmd(path, b64(line), key + '=', envFile + '.env.attempt' + attempt + '.bak') });
}
return block('unknown action: ' + action);

const v = $('Validate and Build Command').item.json;
if (v.allowed === false) { return [{ json: { ok: false, action: v.action, blocked: true, message: v.message } }]; }
const ssh = $json;
const raw = String(ssh.stdout || '');
const NEWLINE = String.fromCharCode(10);
let output = raw;
if (v.mode === 'read') {
  const lines = raw.split(NEWLINE).map(function (l) {
    const low = String(l).toLowerCase();
    if (low.indexOf('db_password') !== -1 || low.indexOf('password') !== -1 || low.indexOf('secret') !== -1 || low.indexOf('token') !== -1 || low.indexOf('app_key') !== -1 || low.indexOf('private') !== -1) {
      const ci = l.indexOf(':'); const ei = l.indexOf('=');
      let sep = -1;
      if (ci !== -1 && (ei === -1 || ci < ei)) sep = ci; else if (ei !== -1) sep = ei;
      if (sep !== -1) return l.slice(0, sep + 1) + ' [PROTECTED]';
      return '[PROTECTED]';
    }
    return l;
  });
  output = lines.join(NEWLINE);
}
const okFlag = (ssh.code === 0);
return [{ json: { ok: okFlag, action: v.action, mode: v.mode, path: v.safePath || '', output: output.slice(0, 12000) } }];
